package com.opensocket.aievent.core.iam.api.request;import java.util.Set;public record TokenScopeRequest(Set<String> permissions,Set<String> audiences,Set<String> apiPrefixes,Set<String> allowedCidrs){public TokenScopeRequest{permissions=permissions==null?Set.of():Set.copyOf(permissions);audiences=audiences==null?Set.of():Set.copyOf(audiences);apiPrefixes=apiPrefixes==null?Set.of():Set.copyOf(apiPrefixes);allowedCidrs=allowedCidrs==null?Set.of():Set.copyOf(allowedCidrs);}}